    type: "landmark",
    name: { de: "Kulturelle Stätten der Marovo Lagune", hu: "Marovo-lagúna kulturális helyszínei", ro: "Siturile culturale din Laguna Marovo", en: "Marovo Lagoon Cultural Sites" },
    coords: [158.15, -8.4833],
